Before you conﬁgure IAM Identity Center, you must update the domain access policy or
the permissions of the IAM role conﬁgured in OpenSearch applications for Trusted Identity
Propagation.
JSON
{
"Version":"2012-10-17",
"Statement": [
{
"Effect": "Allow",
"Principal": {
"AWS": "arn:aws:iam::111122223333:role/OpenSearchRole"
},
"Action": "es:ESHttp*",
"Resource": "arn:aws:es:us-east-1:111122223333:domain/example-domain/
*"
}
]
}
